    {
      "rank": 1,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum seeding of structure provide a remarkably powerful framework for the observable universe.",
        "attribution": "The listed theorists represent central distinct steps: the inflationary proposal, its development, and the fluctuation mechanism.",
        "maturity": "CMB and large-scale-structure observations strongly support much of the framework and its central predictions.",
        "uncertainties": [
          "The detailed inflationary mechanism remains undetermined, and primordial tensor modes have not been detected.",
          "Credit for the broader inflationary idea and perturbation theory is inherently distributed."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP transformed cosmology into precision physics and established a durable quantitative account of cosmic parameters.",
        "attribution": "These names plausibly cover the mission's scientific leadership and interpretation, though a major collaboration was essential.",
        "maturity": "Its measurements have been extensively checked, elaborated by later observations, and have permanently shaped cosmology.",
        "uncertainties": [
          "The appropriate division of credit between mission leadership, instrumentation, analysis, and the wider collaboration requires close review."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "Shaun Cole",
        "Will J. Percival"
      ],
      "assessment": {
        "nobel_worthiness": "BAO supplied a robust cosmic standard ruler and a particularly elegant observational handle on expansion history.",
        "attribution": "The nominated scientists made seminal observational demonstrations, while the underlying idea and survey work have broad roots.",
        "maturity": "Repeated detections across surveys have made BAO a standard and reliable cosmological probe.",
        "uncertainties": [
          "Attribution must distinguish the theoretical proposal, first measurements, and the many survey collaborations."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric phase and the Aharonov-Bohm effect revealed profound, experimentally consequential aspects of quantum mechanics.",
        "attribution": "The two named scientists are unmistakably associated with the respective foundational insights.",
        "maturity": "Both effects have long been experimentally established and have influenced diverse areas of physics.",
        "uncertainties": [
          "Combining two related but historically distinct discoveries into one award would need careful justification."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have pushed timekeeping and precision tests to an extraordinary new regime.",
        "attribution": "Katori and Ye are leading originators of the decisive lattice-clock concepts and realizations.",
        "maturity": "The technology is highly reproducible, internationally adopted, and already supports major applications and fundamental tests.",
        "uncertainties": [
          "Its ultimate impact on a redefinition of the second and on new fundamental discoveries is still unfolding."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube opened high-energy neutrino astronomy, adding a genuinely new observational channel to the universe.",
        "attribution": "Halzen is a compelling representative of the scientific vision and leadership, though the result is deeply collaborative.",
        "maturity": "The astrophysical neutrino flux and subsequent source associations establish the field beyond an isolated observation.",
        "uncertainties": [
          "A single laureate may inadequately represent the detector, analysis, and collaboration-wide achievement."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Richard N. Manchester"
      ],
      "assessment": {
        "nobel_worthiness": "The nanohertz gravitational-wave background is an impressive new confirmation that the gravitational-wave universe extends across vast timescales.",
        "attribution": "The listed figures have made major pulsar-timing contributions, but the discovery emerged through several international collaborations.",
        "maturity": "Independent pulsar-timing arrays have reported consistent evidence, making the signal highly compelling.",
        "uncertainties": [
          "The result is recent and its detailed source population and spectral interpretation remain under active examination.",
          "Attribution across the participating arrays is unusually difficult."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Edward Witten",
        "Juan Maldacena"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is among the deepest conceptual advances in modern theoretical physics and has had exceptional reach.",
        "attribution": "Maldacena's formulation is pivotal, with Witten central to its development; the intellectual lineage is broader than any short list.",
        "maturity": "The correspondence has generated a mature and extraordinarily productive theoretical research programme.",
        "uncertainties": [
          "Direct empirical confirmation remains absent.",
          "The nominated attribution, including the role of earlier developments, requires particularly careful historical scrutiny."
        ]
      }
    }
  ]
}
